//! The compiled bundled extension packages: manifests and JavaScript sources
//! captured at build time from `extensions/@knot`.

/// One bundled package: its manifest text and compiled modules, keyed by the
/// `dist/…` path they are admitted under.
pub struct BundledSource {
    pub manifest: &'static str,
    pub sources: &'static [(&'static str, &'static str)],
}

// Generated by build.rs from every package under extensions/@knot.
include!(concat!(env!("OUT_DIR"), "/bundled_packages.rs"));
